{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.raw_sku_demand_projection_fact_items as with sku_drr as ( with daily_sales as ( SELECT sku, date(order_date) AS order_date, sum(units_sold) AS daily_units_sold FROM hyuman-wh.maplemonk.hyuman_drr_sales_consolidated_intermediate WHERE order_date >= date_sub(current_date()-1,interval 28 DAY) AND order_date < current_date() - 1 GROUP BY 1, 2 ), sku_averages AS ( SELECT sku, round( SAFE_DIVIDE( sum(daily_units_sold), count(DISTINCT CASE WHEN daily_units_sold <> 0 THEN order_date END) ) / 2, 2 ) AS average FROM daily_sales GROUP BY 1 ), dynamic_drr AS ( SELECT ds.sku, sa.average, round( SAFE_DIVIDE( sum( CASE WHEN ds.order_date >= date_sub(current_date()-1,interval 7 DAY) AND ds.order_date < current_date()-1 AND ds.daily_units_sold >= sa.average THEN ds.daily_units_sold ELSE 0 END ), count( DISTINCT CASE WHEN ds.order_date >= date_sub(current_date()-1,interval 7 DAY) AND ds.order_date < current_date()-1 AND ds.daily_units_sold <> 0 AND ds.daily_units_sold >= sa.average THEN ds.order_date END ) ), 2 ) AS drr_7, round( SAFE_DIVIDE( sum( CASE WHEN ds.order_date >= date_sub(current_date()-1,interval 14 DAY) AND ds.order_date < current_date()-1 AND ds.daily_units_sold >= sa.average THEN ds.daily_units_sold ELSE 0 END ), count( DISTINCT CASE WHEN ds.order_date >= date_sub(current_date()-1,interval 14 DAY) AND ds.order_date < current_date()-1 AND ds.daily_units_sold <> 0 AND ds.daily_units_sold >= sa.average THEN ds.order_date END ) ), 2 ) AS drr_14, round( SAFE_DIVIDE( sum( CASE WHEN ds.order_date >= date_sub(current_date()-1,interval 28 DAY) AND ds.order_date < current_date()-1 AND ds.daily_units_sold >= sa.average THEN ds.daily_units_sold ELSE 0 END ), count( DISTINCT CASE WHEN ds.order_date >= date_sub(current_date()-1,interval 28 DAY) AND ds.order_date < current_date()-1 AND ds.daily_units_sold <> 0 AND ds.daily_units_sold >= sa.average THEN ds.order_date END ) ), 2 ) AS drr_28 FROM daily_sales AS ds JOIN sku_averages AS sa ON ds.sku = sa.sku GROUP BY 1, 2 ) SELECT sku, average, coalesce(drr_7, 0) AS drr_7, coalesce(drr_14, 0) AS drr_14, coalesce(drr_28, 0) AS drr_28, greatest(coalesce(drr_7, 0), coalesce(drr_14, 0), coalesce(drr_28, 0)) AS max_drr, ( coalesce(drr_7, 0) * 0.3 + coalesce(drr_14, 0) * 0.3 + coalesce(drr_28, 0) * 0.4 ) AS weighted_avg_drr, CASE WHEN coalesce(drr_7, 0) = 0 OR coalesce(drr_14, 0) = 0 THEN greatest(coalesce(drr_7, 0), coalesce(drr_14, 0), coalesce(drr_28, 0)) ELSE ( coalesce(drr_7, 0) * 0.3 + coalesce(drr_14, 0) * 0.3 + coalesce(drr_28, 0) * 0.4 ) END AS final_drr FROM dynamic_drr ), sku_child_mapping as ( select trim(upper(sku_code)) as sku_code, trim(upper(raw_sku)) as raw_sku, trim(upper(raw_sku_name)) as raw_sku_name, cast(Raw_SKU_Quantity as int64) as raw_sku_qty from `MapleMonk.GS_Child_SKU_to_raw_material` qualify row_number() over (partition by trim(upper(sku_code)),trim(upper(raw_sku)) order by 1 desc)=1 ), in_transit_by_wh as( select cast(parse_date(\'%d/%m/%Y\',PO_Date) as date) as po_date, trim(upper(Unique_Identifier__if_any_)) as po_id, trim(upper(SKU)) as skuCode, trim(upper(Warehouse)) as facility, cast(trim(Ordered_Quantity__Total_Ordered_Quantity_) as int64) as ordered_quantity, cast(trim(Pending_Quantity__Stock_in_Transfer_) as int64) as pending_quantity from `MapleMonk.GS_In_Transit_by_Warehouse` where trim(upper(status)) = \'IN TRANSIT\' ), in_transit_raw as ( select upper(trim(sku)) as raw_sku, cast(trim(stock_in_transit) as int64) as in_transit_stock from `MapleMonk.GS_In_Transit_by_Vendor_Hyuman` qualify row_number() over (partition by upper(trim(sku)) order by 1 desc)=1 ), latest_inventory as ( select * from maplemonk.unicommerce_get_inventory_snapshot qualify row_number() over (partition by facility,skuCode order by DATETIME(TIMESTAMP(timestamp), \'Asia/Kolkata\') desc) = 1 ), child_inv as ( select c.raw_sku, sum(case when upper(facility) in (\'HYUMAN_HYD\',\'HYUMAN_BLR\',\'HYUMAN_MUM\',\'HYUMAN_GGN\',\'HYUMAN_HYD\') then cast(inventory as int64) * c.raw_sku_qty else 0 end) as sr_inventory, sum(ifnull(cast(inventory as int64),0) * c.raw_sku_qty) as current_inventory, from latest_inventory i left join sku_child_mapping c on trim(upper(c.sku_code)) = upper(i.skucode) group by c.raw_sku ), child_drr as ( select c.raw_sku_name, raw_sku, round(sum(raw_sku_qty * round(final_drr,2)),2) as child_drr from sku_drr left join sku_child_mapping c on trim(upper(sku_code)) = upper(sku) group by 1,2 ) select cast(null as date) as date, split(c.raw_sku,\'RAW\')[offset(1)] as raw_sku, c.raw_sku_name, c.child_drr as raw_sku_drr, i.current_inventory, cast(round(safe_divide(i.current_inventory ,child_drr)) as int64) as current_doh, it.in_transit_stock as in_transit_vendor from child_drr c left join child_inv i on upper(i.raw_sku) = upper(c.raw_sku) left join in_transit_raw it on upper(it.raw_sku) = upper(c.raw_sku) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            